    $name = 'BookOpen';
  }

  $definition = $icons[$name];
  $class = $options['class'] ?? 'thumb-icon';
  return '<svg viewBox="0 0 256 256" class="' . e($class) . '" focusable="false">'
    . $definition
    . '</svg>';
}

